/**
 * PlayableSDK — wrapper tracking analytics events.
 */

export enum ALEvent {
    LOADING = 'LOADING',
    LOADED = 'LOADED',
    DISPLAYED = 'DISPLAYED',
    CHALLENGE_STARTED = 'CHALLENGE_STARTED',
    CHALLENGE_PASS_25 = 'CHALLENGE_PASS_25',
    CHALLENGE_PASS_50 = 'CHALLENGE_PASS_50',
    CHALLENGE_PASS_75 = 'CHALLENGE_PASS_75',
    CHALLENGE_SOLVED = 'CHALLENGE_SOLVED',
    CHALLENGE_FAILED = 'CHALLENGE_FAILED',
    CHALLENGE_RETRY = 'CHALLENGE_RETRY',
    ENDCARD_SHOWN = 'ENDCARD_SHOWN',
    CTA_CLICKED = 'CTA_CLICKED',
}

export class PlayableSDK {
    static track(event: string | ALEvent) {
        try {
            const analytics = (window as any).ALPlayableAnalytics;
            if (analytics && typeof analytics.trackEvent === 'function') {
                analytics.trackEvent(event);
            }
        } catch (e) {
            console.warn('[PlayableSDK] track error:', e);
        }
    }
}
